using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 5%: 249.95 -> 249 off
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // 50.00 enters the 1-point band
    [InlineData(LoyaltyTier.Green, 10_000, 9_400)]
    [InlineData(LoyaltyTier.Green, 19_999, 18_800)]  // 6%: 1199.94 -> 1199 off
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 200.00 enters the 3-point band
    [InlineData(LoyaltyTier.Gold, 4_999, 4_650)]
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10 points, at the cap
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)]
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]  // 10 points, at the cap
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // 12 capped to 10
    [InlineData(LoyaltyTier.Green, 0, 0)]
    [InlineData(LoyaltyTier.Green, 19, 19)]          // discount 0.95 cent rounds down to 0
    [InlineData(LoyaltyTier.Green, 39, 38)]          // 1.95 cents -> 1
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var payable = new CalculatePayableTotal().For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, payable);
    }
}
E
